                                      {/* Delete button - always available */}
                                      <button
                                        className="flex-1 px-4 py-2 bg-gradient-to-r from-red-500 to-pink-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2"
                                        onClick={() =>
                                          handleDeleteReport(report.id)
                                        }
                                      >
                                        <span className="material-icons text-sm">
                                          delete
                                        </span>
                                        Delete
                                      </button>
                                    </div>
                                  </div>
                                </div>
                              ))
                            ) : (
                              <div className="col-span-full text-center py-12">
                                <span className="material-icons text-6xl text-gray-300 mb-4">
                                  search
                                </span>
                                <p className="text-gray-500 text-lg">
                                  No rescue pet reports yet
                                </p>
                              </div>
                            )}
                          </div>
                        </div>
                      )}
                    </div>

                    {user?.role === "admin" && adminMetrics && (
                      <div className="admin-metrics">
                        <h3>Admin Dashboard Metrics</h3>
                        <ul>
                          <li>
                            Total Pets Reported:{" "}
                            {adminMetrics.total_pets_reported}
                          </li>
                          <li>
                            Total Adoptions Approved:{" "}
                            {adminMetrics.total_adoptions_approved}
                          </li>
                          <li>Total Lost: {adminMetrics.total_lost}</li>
                          <li>Total Found: {adminMetrics.total_found}</li>
                          <li>
                            Total Registered Users:{" "}
                            {adminMetrics.total_registered_users}
                          </li>
                          <li>
                            Total Cases Resolved:{" "}
                            {adminMetrics.total_cases_resolved}
                          </li>
                        </ul>
                        {metricsMsg && <div>{metricsMsg}</div>}
                      </div>
                    )}

                    {/* Section 3: MY ADOPTION POSTS */}
                    <div className="bg-gradient-to-br from-purple-200 to-purple-250 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-lg border border-blue-100 dark:border-slate-600 overflow-hidden">
                      <button
                        onClick={() =>
                          setExpandedSection(
                            expandedSection === "adoptionPosts"
                              ? null
                              : "adoptionPosts"
                          )
                        }
                        className="w-full flex items-center justify-between p-6 hover:bg-blue-50 dark:hover:bg-slate-700 transition-colors"
                      >
                        <div className="flex items-center gap-3">
                          <span className="material-icons text-accent-yellow text-3xl">
                            volunteer_activism
                          </span>
                          <h2 className="text-2xl font-bold text-gray-800 dark:text-white">
                            MY ADOPTION POSTS ({myAdoptionPosts.length})
                          </h2>
                        </div>
                        <span
                          className={`material-icons text-3xl text-accent-yellow transition-transform ${
                            expandedSection === "adoptionPosts"
                              ? "rotate-180"
                              : ""
                          }`}
                        >
                          expand_more
                        </span>
                      </button>

                      {expandedSection === "adoptionPosts" && (
                        <div className="p-6 pt-0">
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            {myAdoptionPosts.length > 0 ? (
                              myAdoptionPosts.map((post) => (
                                <div
                                  key={post.id}
                                  className="bg-gradient-to-br from-white to-blue-50 dark:from-slate-800 dark:to-blue-900 rounded-2xl shadow-lg overflow-hidden hover:shadow-2xl transition-all duration-300 transform hover:-translate-y-2 border border-blue-200 dark:border-blue-700"
                                >
                                  <div className="relative h-56 overflow-hidden">
                                    <img
                                      src={getImageUrl(post.image)}
                                      alt={post.name}
                                      className="w-full h-full object-cover"
                                      onError={(e) => {
                                        e.target.src = "/default-pet.png";
                                      }}
                                    />
                                      {/* Favourite toggle (top-right) for user's adoption posts */}
                                      {post.id && (
                                        <button
                                          onClick={async (e) => {
                                            e.stopPropagation();
                                            const fav = findFavouriteByPetId(post.id);
                                            if (fav) await handleRemoveFavourite(fav.id);
                                            else await handleAddFavourite(post.id);
                                          }}
                                          title={findFavouriteByPetId(post.id) ? "Remove favourite" : "Add to favourites"}
                                          aria-pressed={!!findFavouriteByPetId(post.id)}
                                          className={`absolute top-3 right-3 z-10 p-2 rounded-full shadow-md transition-colors ${findFavouriteByPetId(post.id) ? 'bg-pink-500 text-white' : 'bg-white text-gray-800 dark:bg-slate-700 dark:text-white'}`}
                                        >
                                          <span className="material-icons">favorite</span>
                                        </button>
                                      )}
                                    <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/70 to-transparent p-4">
                                      <h3 className="text-white font-bold text-lg">
                                        {post.name}
                                      </h3>
                                    </div>
                                  </div>
                                  <div className="p-5 space-y-3">
                                    <div className="inline-block px-3 py-1 bg-yellow-100 text-accent-yellow rounded-full text-sm font-semibold">
                                      {post.type}
                                    </div>
                                    <div className="space-y-2">
                                      {post.breed && (
                                        <span className="block text-gray-700 dark:text-white text-sm">
                                          <span className="font-semibold">
                                            Breed:
                                          </span>{" "}
                                          {post.breed}
                                        </span>
                                      )}
                                      <span className="block text-gray-700 dark:text-white text-sm">
                                        <span className="font-semibold">
                                          Age:
                                        </span>{" "}
                                        🎂 {post.age} years
                                      </span>
                                      <span className="block text-gray-700 dark:text-white text-sm">
                                        <span className="font-semibold">
                                          Gender:
                                        </span>{" "}
                                        {post.gender === "Male" ? "♂️" : "♀️"}{" "}
                                        {post.gender}
                                      </span>
                                      {post.location && (
                                        <span className="flex items-center gap-1 text-gray-700 dark:text-white text-sm">
                                          <span className="material-icons text-xs">
                                            location_on
                                          </span>
                                          {post.location}
                                        </span>
                                      )}
                                    </div>
                                    <p className="text-gray-600 dark:text-white text-sm leading-relaxed">
                                      {post.description
                                        ? post.description.length > 100
                                          ? `${post.description.substring(
                                              0,
                                              100
                                            )}...`
                                          : post.description
                                        : "No description available"}
                                    </p>
                                    <div className="flex flex-wrap gap-2">
                                      {post.is_vaccinated && (
                                        <span className="px-2 py-1 bg-green-100 text-green-700 dark:bg-green-800 dark:text-green-100 rounded-full text-xs font-semibold">
                                          ✓ Vaccinated
                                        </span>
                                      )}
                                      {post.is_diseased && (
                                        <span className="px-2 py-1 bg-orange-100 text-orange-700 rounded-full text-xs font-semibold">
                                          ⚠ Health Condition
                                        </span>
                                      )}
                                    </div>
                                    <div
                                      className={`px-3 py-2 rounded-lg text-center font-semibold text-sm ${
                                        post.report_status === "accepted"
                                          ? "bg-green-100 text-green-700 dark:bg-green-800 dark:text-green-100"
                                          : post.report_status === "pending"
                                          ? "bg-yellow-100 text-yellow-700 dark:bg-yellow-800 dark:text-yellow-100"
                                          : "bg-red-100 text-red-700 dark:bg-red-800 dark:text-red-100"
                                      }`}
                                    >
                                      {post.report_status === "pending" &&
                                        "⏳ PENDING REVIEW"}
                                      {post.report_status === "accepted" &&
                                        "✅ APPROVED"}
                                      {post.report_status === "rejected" &&
                                        "❌ REJECTED"}
                                    </div>
                                    {post.admin_comment && (
                                      <div className="bg-gray-50 p-3 rounded-lg text-sm">
                                        <strong className="text-gray-700 dark:text-white">
                                          Admin:
                                        </strong>
                                        <p className="text-gray-600 dark:text-white mt-1">
                                          {post.admin_comment}
                                        </p>
                                      </div>
                                    )}
                                    <div className="flex items-center justify-between pt-2 border-t border-gray-100">
                                      <span className="text-xs text-gray-500 dark:text-slate-300">
                                        Posted:{" "}
                                        {new Date(
                                          post.created_at
                                        ).toLocaleDateString()}
                                      </span>
                                    </div>

                                    {/* View Details Button */}
                                    <button
                                      className="w-full px-4 py-2 bg-gradient-to-r from-yellow-500 to-orange-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2 mt-2"
                                      onClick={() => {
                                        if (post.pet_id) {
                                          fetchPetDetails(post.pet_id);
                                        } else {
                                          setError(
                                            "Pet ID not available for this post"
                                          );
                                          setTimeout(() => setError(""), 3000);
                                        }
                                      }}
                                    >
                                      <span className="material-icons text-sm">
                                        visibility
                                      </span>
                                      View Details
                                    </button>

                                    {/* Delete Button for Adoption Posts */}
                                    <button
                                      className="w-full px-4 py-2 bg-gradient-to-r from-red-500 to-pink-500 text-white font-semibold rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-300 flex items-center justify-center gap-2 mt-2"
                                      onClick={() =>
                                        handleDeleteReport(post.id)
                                      }
                                    >
                                      <span className="material-icons text-sm">
                                        delete
                                      </span>
                                      Delete Post
                                    </button>
                                  </div>
                                </div>
                              ))
                            ) : (
                              <div className="col-span-full text-center py-12">
                                <span className="material-icons text-6xl text-gray-300 mb-4">
                                  volunteer_activism
                                </span>
                                <p className="text-gray-500 text-lg">
                                  You haven't posted any pets for adoption yet
                                </p>
                              </div>
                            )}
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                ))}

              {activeTab === "report-lost" && (
                <div className="bg-gradient-to-br from-purple-200 to-purple-250 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-xl p-8 border-2 border-purple-200 dark:border-slate-600">
                  <div className="flex items-center gap-3 mb-6 pb-3 border-b-2 border-primary-blue">
                    <span className="material-icons text-primary-blue text-3xl">
                      report
                    </span>
                    <h2 className="text-2xl font-bold text-gray-800 dark:text-white">
                      REPORT LOST PET
                    </h2>
                  </div>
                  <form onSubmit={handleSubmitPetReport} className="space-y-6">
                    <input type="hidden" name="pet_status" value="lost" />

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      <div className="flex flex-col">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Pet Name *
                        </label>
                        <input
                          type="text"
                          name="pet_name"
                          value={petForm.pet_name}
                          onChange={handleFormChange}
                          required
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                          placeholder="Enter pet name"
                        />
                      </div>

                      <div className="flex flex-col">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Pet Type *
                        </label>
                        <select
                          name="pet_type"
                          value={petForm.pet_type}
                          onChange={handleFormChange}
                          required
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors bg-slate-50/50"
                        >
                          <option value="Dog">Dog</option>
                          <option value="Cat">Cat</option>
                          <option value="Bird">Bird</option>
                          <option value="Other">Other</option>
                        </select>
                      </div>

                      <div className="flex flex-col">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Breed
                        </label>
                        <input
                          type="text"
                          name="pet_breed"
                          value={petForm.pet_breed}
                          onChange={handleFormChange}
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                          placeholder="Enter breed"
                        />
                      </div>

                      <div className="flex flex-col">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Age
                        </label>
                        <input
                          type="number"
                          name="pet_age"
                          value={petForm.pet_age}
                          onChange={handleFormChange}
                          min="0"
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                          placeholder="Enter age"
                        />
                      </div>

                      <div className="flex flex-col">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Color
                        </label>
                        <input
                          type="text"
                          name="pet_colour"
                          value={petForm.pet_colour}
                          onChange={handleFormChange}
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                          placeholder="Enter color"
                        />
                      </div>

                      <div className="flex flex-col">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Weight (kg)
                        </label>
                        <input
                          type="number"
                          name="pet_weight"
                          value={petForm.pet_weight}
                          onChange={handleFormChange}
                          step="0.1"
                          min="0"
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                          placeholder="Enter weight"
                        />
                      </div>

                      <div className="flex flex-col">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Gender
                        </label>
                        <select
                          name="pet_gender"
                          value={petForm.pet_gender}
                          onChange={handleFormChange}
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors bg-slate-50/50"
                        >
                          <option value="Male">Male</option>
                          <option value="Female">Female</option>
                          <option value="Unknown">Unknown</option>
                        </select>
                      </div>

                      <div className="flex flex-col">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Last Seen Location *
                        </label>
                        <input
                          type="text"
                          name="pet_location"
                          value={petForm.pet_location}
                          onChange={handleFormChange}
                          required
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                          placeholder="Enter location"
                        />
                      </div>

                      <div className="flex flex-col">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          State
                        </label>
                        <input
                          type="text"
                          name="pet_state"
                          value={petForm.pet_state}
                          onChange={handleFormChange}
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                          placeholder="Enter state"
                        />
                      </div>

                      <div className="flex flex-col">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          City
                        </label>
                        <input
                          type="text"
                          name="pet_city"
                          value={petForm.pet_city}
                          onChange={handleFormChange}
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                          placeholder="Enter city"
                        />
                      </div>

                      <div className="flex flex-col md:col-span-2">
                        <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                          Pet Photo
                        </label>
                        <input
                          type="file"
                          name="pet_image"
                          accept="image/*"
                          onChange={(e) => {
                            const file = e.target.files[0];
                            setPetForm((prev) => ({
                              ...prev,
                              pet_image: file,
                            }));
                          }}
                          className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary-blue file:text-white hover:file:bg-primary-teal file:cursor-pointer"
                        />
                        <p className="text-xs text-gray-500 dark:text-slate-300 mt-2">
                          Choose a clear photo of your pet (JPG, PNG, WebP)
                        </p>
                        {petForm.pet_image && (
                          <div className="mt-4 relative inline-block">
                            <img
                              src={URL.createObjectURL(petForm.pet_image)}
                              alt="Pet preview"
                              className="w-32 h-32 object-cover rounded-xl border-2 border-gray-200"
                            />
                            <button
                              type="button"
                              className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-6 h-6 flex items-center justify-center hover:bg-red-600 transition-colors"
                              onClick={() =>
                                setPetForm((prev) => ({
                                  ...prev,
                                  pet_image: null,
                                }))
                              }
                            >
                              ×
                            </button>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="flex flex-col">
                      <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                        Description
                      </label>
                      <textarea
                        name="description"
                        value={petForm.description}
                        onChange={handleFormChange}
                        rows="4"
                        className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors resize-none"
                        placeholder="Describe your pet's appearance, behavior, any distinctive marks..."
                      />
                    </div>

                    <h3 className="text-lg font-bold text-gray-800 dark:text-white mb-4 flex items-center gap-2">
                      <span className="text-2xl">💊</span>
                      Medical Information
                    </h3>
                    <div className="space-y-4">
                      <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-slate-700 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-600 transition-colors">
                        <input
                          type="checkbox"
                          name="is_vaccinated"
                          checked={petForm.is_vaccinated}
                          onChange={handleFormChange}
                          className="w-5 h-5 rounded border-2 border-gray-300 text-primary-blue focus:ring-2 focus:ring-primary-blue focus:ring-offset-2 cursor-pointer"
                        />
                        <label className="text-sm font-medium text-gray-700 dark:text-white cursor-pointer select-none">
                          Is Vaccinated
                        </label>
                      </div>

                      {petForm.is_vaccinated && (
                        <div className="flex flex-col ml-8 animate-fadeIn">
                          <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                            Vaccination Details
                          </label>
                          <input
                            type="text"
                            name="vaccination_details"
                            value={petForm.vaccination_details}
                            onChange={handleFormChange}
                            className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                            placeholder="Enter vaccination details (e.g., Rabies, Distemper, etc.)..."
                          />
                        </div>
                      )}

                      <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-slate-700 rounded-xl hover:bg-gray-100 dark:hover:bg-slate-600 transition-colors">
                        <input
                          type="checkbox"
                          name="is_diseased"
                          checked={petForm.is_diseased}
                          onChange={handleFormChange}
                          className="w-5 h-5 rounded border-2 border-gray-300 text-primary-blue focus:ring-2 focus:ring-primary-blue focus:ring-offset-2 cursor-pointer"
                        />
                        <label className="text-sm font-medium text-gray-700 dark:text-white cursor-pointer select-none">
                          Is Diseased
                        </label>
                      </div>

                      {petForm.is_diseased && (
                        <div className="flex flex-col ml-8 animate-fadeIn">
                          <label className="text-sm font-semibold text-gray-700 dark:text-white mb-2">
                            Health Conditions
                          </label>
                          <input
                            type="text"
                            name="health_conditions"
                            value={petForm.health_conditions}
                            onChange={handleFormChange}
                            className="w-full px-4 py-3 border-2 border-gray-200 dark:border-slate-600 rounded-xl focus:border-primary-blue dark:bg-slate-700 dark:text-white focus:outline-none transition-colors"
                            placeholder="Describe health conditions..."
                          />
                        </div>
                      )}
                    </div>

                    <div className="flex flex-col-reverse sm:flex-row gap-4 mt-8 pt-6 border-t-2 border-gray-100">
                      <button
                        type="button"
                        onClick={() => setActiveTab("dashboard")}
                        className="flex-1 px-6 py-3 border-2 border-gray-300 text-gray-700 dark:text-white font-semibold rounded-xl hover:bg-gray-50 hover:border-gray-400 transition-all duration-200"
                      >
                        Cancel
                      </button>
                      <button
                        type="submit"
                        disabled={submitLoading}
                        className="flex-1 px-6 py-3 bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow text-white font-bold rounded-xl hover:shadow-lg hover:scale-105 transition-all duration-200 disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100 disabled:hover:shadow-none"
                      >
                        {submitLoading ? (
                          <span className="flex items-center justify-center gap-2">
                            <svg
                              className="animate-spin h-5 w-5"
                              viewBox="0 0 24 24"
                            >
                              <circle
                                className="opacity-25"
                                cx="12"
                                cy="12"
                                r="10"
                                stroke="currentColor"
                                strokeWidth="4"
                                fill="none"
                              />
                              <path
                                className="opacity-75"
                                fill="currentColor"
                                d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                              />
                            </svg>
                            Submitting...
                          </span>
                        ) : (
                          "Report Lost Pet"
                        )}
                      </button>
                    </div>
                  </form>
                </div>
              )}
              {/* /////////////////////////// */}
              

              {activeTab === "report-found" && (
                <div className="bg-gradient-to-br from-purple-200 to-purple-250 dark:from-slate-800 dark:to-slate-700 rounded-2xl shadow-xl p-8 border-2 border-purple-200 dark:border-slate-600">
                  <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                    <span className="text-3xl bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                      👁️
                    </span>
                    <span className="bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                      REPORT FOUND PET
