                              pet_name: "",
                              pet_type: "Dog",
                              pet_breed: "",
                              pet_age: "",
                              pet_colour: "",
                              pet_weight: "",
                              pet_gender: "Male",
                              pet_location: "",
                              pet_state: "",
                              pet_city: "",
                              pet_status: "found",
                              description: "",
                              is_vaccinated: false,
                              is_diseased: false,
                              vaccination_details: "",
                              health_conditions: "",
                            });
                            loadData();
                            setTimeout(() => setActiveTab("dashboard"), 2000);
                          }
